PATCH_MAP={'motion_choreography':('MotionPrimitive','replace_or_retime_lowest_confidence_motion'),'composition':('Beat','rebalance_focal_hierarchy_and_safe_areas'),'style_coherence':('Style','tighten_style_tokens_and_remove_outliers'),'typography':('Text','increase_readability_and_lock_exact_type'),'transition_quality':('Transition','replace_generic_transition_with_motivated_match_motion'),'asset_realism':('Asset','upgrade_material_detail_and_photorealism'),'brand_adherence':('Style','reapply_brand_constraints'),'narrative_clarity':('Beat','simplify_or_merge_low_value_beats'),'technical_integrity':('Renderer','repair_render_or_timing_contract'),'final_frame_memorability':('Beat','strengthen_final_memory_anchor_and_hold'),'focal_hierarchy':('Beat','rebalance_focal_hierarchy'),'composition_balance':('Beat','repair_crops_and_visual_weight'),'typography_integrity':('Text','fit_exact_typography_to_safe_area'),'motion_motivation':('MotionPrimitive','replace_unmotivated_motion'),'transition_motivation':('Transition','replace_with_object_or_match_motion')}
def plan_patches(scores,defects,target=9.0,limit=4):
    patches=[]
    for d in defects:patches.append({'priority':100 if d['severity']=='P0' else 90 if d['severity']=='P1' else 70,'target_kind':'Renderer','action':'fix_defect','reason':d['code'],'defect':d})
    for v,k in sorted((v,k) for k,v in scores.items() if v<target):
        kind,action=PATCH_MAP.get(k,('Beat','manual_review'));patches.append({'priority':round((target-v)*10,2),'target_kind':kind,'action':action,'reason':f'{k}={v:.3f} below {target:.1f}','dimension':k})
    return sorted(patches,key=lambda x:x['priority'],reverse=True)[:limit]
